#!/usr/bin/env node
// Sync the canonical using-specialists skill into the Claude Code plugin.
//
// The plugin carries a byte-identical copy of the skill because a marketplace
// install copies only the plugin folder into Claude Code's cache and cannot run
// the package build. The copy is therefore generated by THIS script and
// committed to git — never built at install time.
//
//   node scripts/sync-plugin-skill.mjs          copy canonical -> plugin
//   node scripts/sync-plugin-skill.mjs --check  exit 1 when the copy differs, write nothing
//
// `evals/` is excluded on both sides to mirror package.json `files`
// (`!config/skills/**/evals/**`): eval fixtures ship in the repo, not in the
// plugin payload — the same reason the installed global pool has no evals dir.

import { createHash } from 'node:crypto';
import { cpSync, mkdirSync, readdirSync, readFileSync, rmSync, statSync } from 'node:fs';
import { join, relative, sep } from 'node:path';

const ROOT = process.cwd();
const SRC = join(ROOT, 'config', 'skills', 'using-specialists');
const DEST = join(ROOT, 'plugins', 'specialists', 'skills', 'using-specialists');

const isEvalPath = (absolutePath) =>
  relative(SRC, absolutePath).split(sep).includes('evals');

function walk(dir) {
  return readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
    const full = join(dir, entry.name);
    if (isEvalPath(full)) return [];
    if (entry.isDirectory()) return walk(full);
    return entry.isFile() ? [full] : [];
  });
}

function sha256(path) {
  return createHash('sha256').update(readFileSync(path)).digest('hex');
}

function snapshot(dir, base) {
  const map = new Map();
  if (!existsSync(dir)) return map;
  for (const file of walk(dir)) {
    map.set(relative(base, file).split(sep).join('/'), sha256(file));
  }
  return map;
}

function existsSync(path) {
  try {
    statSync(path);
    return true;
  } catch {
    return false;
  }
}

const check = process.argv.includes('--check');
const srcFiles = walk(SRC);
const srcMap = new Map(
  srcFiles.map((file) => [relative(SRC, file).split(sep).join('/'), sha256(file)]),
);
const destMap = snapshot(DEST, DEST);

const drifted = [];
for (const [rel, hash] of srcMap) {
  if (!destMap.has(rel)) drifted.push(`missing in plugin copy: ${rel}`);
  else if (destMap.get(rel) !== hash) drifted.push(`differs: ${rel}`);
}
for (const rel of destMap.keys()) {
  if (!srcMap.has(rel)) drifted.push(`stale in plugin copy: ${rel}`);
}

if (check) {
  if (drifted.length > 0) {
    console.error(`plugin skill copy differs:\n  ${drifted.join('\n  ')}`);
    process.exit(1);
  }
  console.log('plugin skill copy matches the canonical skill');
  process.exit(0);
}

rmSync(DEST, { recursive: true, force: true });
mkdirSync(DEST, { recursive: true });
for (const file of srcFiles) {
  const rel = relative(SRC, file);
  const target = join(DEST, rel);
  mkdirSync(join(target, '..'), { recursive: true });
  cpSync(file, target);
}
console.log(`synced ${srcFiles.length} files to plugins/specialists/skills/using-specialists/`);
